namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;

    private readonly List<Notification> _notifications =
    [
        new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
        new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-10)),
        new(3, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-2)),
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    /// <summary>
    /// Returns only notifications newer than the given timestamp.
    /// Simulates a new notification appearing roughly every 15 seconds.
    /// </summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_notifications)
        {
            // Simulate a new notification arriving occasionally
            if (Random.Shared.Next(0, 3) == 0)
            {
                var id = _nextId++;
                _notifications.Add(new Notification(id,
                    $"New event #{id} just happened.", DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Timestamp > since)
                              .OrderByDescending(n => n.Timestamp)
                              .ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading…</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private DateTime lastCheck = DateTime.MinValue;
    private CancellationTokenSource? cts;

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when state wasn't restored from prerender
        notifications ??= await NotificationSvc.GetNotificationsAsync();

        if (notifications.Count > 0)
        {
            lastCheck = notifications.Max(n => n.Timestamp);
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender,
        // so the polling loop only starts once the page is interactive.
        if (firstRender)
        {
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), token);

            var newer = await NotificationSvc.GetNotificationsSinceAsync(lastCheck);
            if (newer.Count > 0)
            {
                notifications = [..newer, ..notifications!];
                lastCheck = notifications.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

